function calcularFatorialGrande(n: number): bigint {
  let resultado = 1n;
  for (let i = 2n; i <= BigInt(n); i++) {
    resultado *= i;
  }
  return resultado;
}

console.log(calcularFatorialGrande(10)); // 3628800n

export interface ConfiguracaoModulo {
  nome: string;
  ativo: boolean;
}

export function criarConfiguracao(nome: string): ConfiguracaoModulo {
  return { nome, ativo: true };
}

const configuracao = criarConfiguracao("exemplo");
console.log(configuracao.nome, configuracao.ativo); // exemplo true

export function converterParaMinutos(segundos: number): number {
  return segundos / 60;
}

console.log(converterParaMinutos(120)); // 2

