function obterUltimoElemento<T>(lista: T[]): T | undefined {
  // at(-1) é um método de ES2022: só está disponível se o target (e o lib associado)
  // for ES2022 ou superior.
  return lista.at(-1);
}

console.log(obterUltimoElemento([10, 20, 30])); // 30
console.log(obterUltimoElemento([])); // undefined

interface ConfiguracaoValida {
  nome: string;
}

function ehConfiguracaoValida(valor: unknown): valor is ConfiguracaoValida {
  return typeof valor === "object" && valor !== null && typeof (valor as ConfiguracaoValida).nome === "string";
}

function lerConfiguracao(json: string): ConfiguracaoValida {
  const analisado: unknown = JSON.parse(json);
  if (!ehConfiguracaoValida(analisado)) {
    throw new Error("JSON sem a propriedade nome (string)");
  }
  return analisado;
}

console.log(lerConfiguracao('{"nome":"curso"}').nome); // curso

try {
  lerConfiguracao('{"outra":1}');
} catch (erro) {
  console.log("erro:", (erro as Error).message); // erro: JSON sem a propriedade nome (string)
}
